namespace ghidra.examples.graph.layout;



using generic.theme;
using ghidra.examples.graph;
using ghidra.graph.viewer.layout;
using ghidra.graph.viewer.layout;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A layout provider for the {@link SampleGraphPlugin}
 */
public class SampleGraphPluginDependencyLayoutProvider : AbstractLayoutProvider<SampleVertex, SampleEdge, SampleGraph> {

	private static readonly string NAME = "Plugin Dependency Layout";
	private static readonly Icon DEFAULT_ICON = new GIcon("icon.sample.graph.dependency.layout");

	/* @Override */
	public VisualGraphLayout<SampleVertex, SampleEdge> getLayout(SampleGraph g, TaskMonitor monitor)
    {

		SampleGraphPluginDependencyLayout layout = new SampleGraphPluginDependencyLayout(g, NAME);
		initVertexLocations(g, layout);
		return layout;
	}

	/* @Override */
	public string getLayoutName() {
		return NAME;
	}

	// Note: each provider really should load its own icon so that the toolbar item can 
	//       signal to the user which layout is active
	/* @Override */
	public Icon getActionIcon() {
		return DEFAULT_ICON;
	}
}
